body {
    font-family: 'Jost', 'Noto Kufi Arabic', sans-serif;
}
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

.mm-container {
    max-width: 388px;
    width: 100%;
    padding: 32px 24px;
    border-radius: 12px;
    border: 1px solid #D2D2D2;
    background: #FFF;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 48px;
    position: relative;
}

.close-icon {
    width: 28px;
    height: 28px;
    border-radius: 24px;
    background: #F0F0F0;
    position: absolute;
    top: 16px;
    right: 16px;
    padding: 10px;
    display: none;
}
.close-icon i{
    height: 10px;
    line-height: 10px;
    width: 10px;
    font-size: 10px;
    color: #000000;
}

.image-container img {
    margin: 0 auto !important;
    display: block;
}

.text-container {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.text-heading {
    font-size: 25px;
    font-weight: 600;
    line-height: 32px;
    color: #191919;
}
.text-iconText-wrapper {
    display: flex;
    flex-direction: column;
    gap: 20px;
}
.iconText-container {
    margin-bottom: 0px !important;
    display: flex;
    align-items: center;
    gap: 16px; 
}
.iconText-container i{
    height: 24px;
    line-height: 24px;
    width: 24px;
    font-size: 24px;
    color: #737373;
}
.iconText-desc {
    font-size: 16px;
    line-height: 24px;
    color: #4C4C4C;
    font-weight: 400;
}

.MM-button {
    font-family: 'Jost', 'Noto Kufi Arabic', sans-serif;
    width: 100%;
    max-width: 100%;
    height: 44px;
    padding: 12px 16px;
    font-size: 16px;
    color: #FFFFFF;
    font-weight: 500;
    line-height: 20px;
    border-radius: 12px;
    background: #6F10A2;
    border: 0px;
    cursor: pointer;
    display: none;
    margin: 0 auto;
    margin-top: 4px;
}

@media screen and (max-width: 767px) {
    .mm-container {
        max-width: 100%;
        padding: 43px 20px 29px 20px;
        border: 0px;
        border-radius: 20px 20px 0px 0px;
    }
    .MM-button {
        display: block;
    }
    .close-icon {
        display: flex;
        align-items: center;
        justify-content: center;
    }
}
